pub fn select_operations(
    backend: &str,
    features: &[&str],
    capabilities: &[&str],
    request: &JSONObject,
) -> Result<Vec<&'static RuntimeOperation>, crate::CodecError> {
    if !["python-legacy", "rust-candidate"].contains(&backend) {
        return Err(crate::CodecError::Invalid(
            "Unknown contract backend".into(),
        ));
    }
    Ok(OPERATIONS
        .iter()
        .filter(|operation| {
            operation.backends.contains(&backend)
                && (backend == "python-legacy"
                    || operation
                        .features
                        .iter()
                        .all(|feature| features.contains(feature))
                        && operation
                            .capabilities
                            .iter()
                            .all(|capability| capabilities.contains(capability))
                        && operation.request_features.iter().all(|condition| {
                            request
                                .get(condition.field)
                                .and_then(serde_json::Value::as_bool)
                                != Some(condition.equals)
                                || features.contains(&condition.feature)
                        }))
        })
        .collect())
}
